#!/bin/bash
# Compare VI at a specific lambda against the AutoFE baselines on a dataset.
#
# Story this script is designed to tell:
#   "Our approach (VI at lam=0.5) trades a small downstream-performance drop
#    for substantially better explainability than the baselines."
#
# Usage:
#   PYTHON=/path/to/python bash run_lambda_compare.sh <dataset> <cuda> [lam] [total_iter] [top_k]
#
# Defaults: lam=0.5, total_iter=10, top_k=16
#
# Assumes:
#   - VI for the chosen lam has already been generated (either by run_iter.sh
#     or run_quality_sweep.sh), OR will be generated by this script.
#   - All baselines should be runnable end-to-end.
#
# Output:
#   outputs/compare/<dataset>_lam<lam>_<timestamp>/
#     ├── compare.log           — full run logs
#     ├── compare.csv           — machine-readable per-row metrics
#     ├── REPORT.md             — summary markdown
#     └── selected_topk_lam<lam>.json + baselines/  — cached features

set -o pipefail

dataset=${1:?missing dataset}
cuda=${2:?missing cuda id}
lam=${3:-0.5}
total_iter=${4:-10}
top_k=${5:-16}

PYTHON=${PYTHON:-python}
MODEL="RF"
N_JOBS=${N_JOBS:-8}

ts=$(date +%Y%m%d_%H%M%S)
CMP_DIR="outputs/compare/${dataset}_lam${lam}_${ts}"
mkdir -p "$CMP_DIR/baselines"
LOG="$CMP_DIR/compare.log"
CSV="$CMP_DIR/compare.csv"
REPORT="$CMP_DIR/REPORT.md"

echo "================================================================" | tee "$LOG"
echo " B-MAFE lambda comparison" | tee -a "$LOG"
echo "  dataset    = $dataset" | tee -a "$LOG"
echo "  lam        = $lam (VI focus)" | tee -a "$LOG"
echo "  total_iter = $total_iter" | tee -a "$LOG"
echo "  top_k      = $top_k" | tee -a "$LOG"
echo "  report dir = $CMP_DIR" | tee -a "$LOG"
echo "================================================================" | tee -a "$LOG"

# ---------- 1. VI@lam ---------------------------------------------------------
VI_OUT="outputs/nfo/${MODEL}/vi/mi/lam${lam}/${dataset}"
VI_CACHE="$VI_OUT/selected_topk_lam${lam}.json"
if [ -f "$VI_CACHE" ]; then
    echo "" | tee -a "$LOG"
    echo "[VI] reusing existing cache: $VI_CACHE" | tee -a "$LOG"
else
    echo "" | tee -a "$LOG"
    echo "##### VI lam=$lam #####" | tee -a "$LOG"
    PYTHON="$PYTHON" bash run_iter.sh "$dataset" "$cuda" "vi" "$total_iter" "mi" "$lam" \
        2>&1 | tee -a "$LOG"
fi
if [ -f "$VI_CACHE" ]; then
    cp "$VI_CACHE" "$CMP_DIR/"
else
    echo "[VI] WARNING: $VI_CACHE not produced; comparison will lack VI row" | tee -a "$LOG"
fi

# ---------- 2. baselines -----------------------------------------------------
BASELINES=("openfe" "autofeat" "eafe" "infer" "lsbo")

run_baseline() {
    local method=$1
    local out="$CMP_DIR/baselines/$method"
    mkdir -p "$out"
    echo "" | tee -a "$LOG"
    echo "##### baseline=$method #####" | tee -a "$LOG"
    local t0=$(date +%s)
    case "$method" in
        openfe)
            "$PYTHON" -m autolearn.feat_selection.openfe_baseline \
                --data "$dataset" --eval_model "$MODEL" --n_jobs "$N_JOBS" \
                --max_top_k "$top_k" --feat_pool "$out" 2>&1 | tee -a "$LOG"
            ;;
        autofeat)
            "$PYTHON" -m autolearn.feat_selection.autofeat_baseline \
                --data "$dataset" --eval_model "$MODEL" --n_jobs "$N_JOBS" \
                --feat_pool "$out" 2>&1 | tee -a "$LOG"
            ;;
        eafe)
            "$PYTHON" -m autolearn.feat_selection.eafe_baseline \
                --data "$dataset" --eval_model "$MODEL" \
                --use_cuda --feat_pool "$out" 2>&1 | tee -a "$LOG"
            ;;
        infer|lsbo)
            PYTHON="$PYTHON" bash run_iter.sh "$dataset" "$cuda" "$method" "$total_iter" "mi" "1.0" \
                2>&1 | tee -a "$LOG"
            local src="outputs/nfo/${MODEL}/${method}/mi/lam1.0/${dataset}/selected_topk_lam1.0.json"
            if [ -f "$src" ]; then
                cp "$src" "$out/eval_manifest.json"
                echo "[$method] copied $src -> $out/eval_manifest.json" | tee -a "$LOG"
            else
                echo "[$method] WARNING: expected $src not found" | tee -a "$LOG"
                return 1
            fi
            ;;
    esac
    local elapsed=$(( $(date +%s) - t0 ))
    echo "[$method] done in ${elapsed}s" | tee -a "$LOG"
}

for method in "${BASELINES[@]}"; do
    if ! run_baseline "$method"; then
        echo "[compare] $method FAILED — continuing" | tee -a "$LOG"
    fi
done

# ---------- 3. unified eval --------------------------------------------------
echo "" | tee -a "$LOG"
echo "##### eval_quality (combined) #####" | tee -a "$LOG"
"$PYTHON" -m autolearn.feat_selection.eval_quality \
    --data "$dataset" \
    --inputs "$CMP_DIR/selected_topk_lam${lam}.json" \
             "$CMP_DIR/baselines/*/eval_manifest.json" \
    --output "$CSV" \
    --top_k "$top_k" \
    2>&1 | tee -a "$LOG"

# ---------- 4. markdown report -----------------------------------------------
{
    echo "# B-MAFE — VI lam=${lam} vs Baselines"
    echo ""
    echo "- **Dataset**: \`$dataset\`"
    echo "- **VI lambda**: $lam  (composite S(f;lam) = lam*MI_norm + (1-lam)*(1-Kext_norm))"
    echo "- **Baselines**: ${BASELINES[*]}"
    echo "- **Top-k evaluated**: $top_k"
    echo "- **Iterations** (VI/INFER/LSBO): $total_iter"
    echo "- **Downstream models**: RF, LR, LGB, XGB"
    echo "- **Generated**: $(date)"
    echo ""
    echo "## How to read"
    echo ""
    echo "- **Usefulness**: model-agnostic feature scores. Higher = better."
    echo "- **Explainability**: Kext (description length) and DBF (distinct base"
    echo "  features). **Lower = simpler/more interpretable**. \`kext_source\` tells"
    echo "  you whether Kext was computed exactly (DIFER tree) or heuristically"
    echo "  (sympy/regex on formula strings)."
    echo "- **Downstream**: 5-fold CV scores on \`[base ∪ derived[:top_k]]\` across"
    echo "  RF/LR/LGB/XGB; \`downstream_avg\` is the mean across the four models."
    echo ""
    echo "## Caveat on Kext fairness"
    echo ""
    echo "Each method uses a different operator vocabulary |O|. Kext is computed"
    echo "with the method's OWN |O|:"
    echo ""
    echo "| Method  | \\|O\\| | Notes |"
    echo "| ---     | --- | --- |"
    echo "| VI / INFER / LSBO / EAFE | 9 | 4 unary + 5 binary numeric |"
    echo "| OpenFE  | ~20 | adds groupby aggregations, freq encoding |"
    echo "| AutoFeat| ~11 | sympy-native ops |"
    echo ""
    echo "This means OpenFE pays a higher per-operator cost in Kext (richer"
    echo "vocabulary), and AutoFeat pays slightly more than DIFER-family."
    echo ""
    echo "## Tables"
    echo ""
    echo '```'
    cat "$LOG" | sed -n '/^=\{4,\}$/,$p' | tail -n +1
    echo '```'
    echo ""
    echo "## Files"
    echo "- \`compare.log\` — full run logs"
    echo "- \`compare.csv\` — per-row metrics (one row per method, plus VI@lam=$lam)"
    echo "- \`selected_topk_lam${lam}.json\` — VI's cached features"
    echo "- \`baselines/<method>/eval_manifest.json\` — baseline caches"
} > "$REPORT"

echo ""
echo "==============================================================="
echo " Comparison report: $CMP_DIR"
echo "   - REPORT.md   (summary markdown)"
echo "   - compare.csv (machine-readable)"
echo "   - compare.log (full logs)"
echo "==============================================================="
